// Камера B-11 после отказа: Chromium с ВСТРОЕННОЙ ТЕСТОВОЙ камерой (зелёная заставка с цифрами, без лица).
// Снимок НЕ делается («צילום» не нажимается) — статус верификации new02 не меняется. Проект data = Chromium.
import { test, expect } from '../../fixtures';
import { saveSession } from '../_shared/session';

test.use({
  launchOptions: { args: ['--use-fake-device-for-media-stream', '--use-fake-ui-for-media-stream'] },
});

test.describe('Верификация лица — камера (тестовое устройство)', () => {
  test.describe.configure({ timeout: 120_000 });

  test('После отказа «לנסות שוב» → B-11: рамка, «המצלמה מוכנה — אפשר לצלם», «צילום»/«דילוג», без петли «מפעילים את המצלמה…» @iphone @data (#4df1ca)', async ({ asUser }) => {
    const p = await asUser('new02');
    try {
      await p.context().grantPermissions(['camera']);
      await p.setViewportSize({ width: 390, height: 844 });
      await p.goto('/verify');
      await expect(p.getByRole('alert')).toBeVisible(); // экран отказа
      await p.getByRole('button', { name: 'לנסות שוב' }).click(); // AC 7: повтор после отказа
      await expect(p.getByText('מקם/י את הפנים בתוך המסגרת')).toBeVisible();
      await expect(p.getByText('המצלמה מוכנה — אפשר לצלם')).toBeVisible();
      await expect(p.getByText(/מפעילים את המצלמה/)).toHaveCount(0); // Р1: нет бесконечной петли
      const shoot = p.getByRole('button', { name: 'צילום' });
      const skip = p.getByRole('button', { name: 'דילוג' });
      await expect(shoot).toBeEnabled();
      await expect(skip).toBeVisible();
      // Под кнопками ничего, кроме «דילוג» (Р2): «דילוג» — самый нижний элемент с текстом.
      const skipBottom = (await skip.boundingBox())!;
      const lowest = await p.evaluate(() => Math.max(...[...document.querySelectorAll('body *')]
        .filter((e) => e.children.length === 0 && (e.textContent || '').trim() && e.getBoundingClientRect().height > 0)
        .map((e) => e.getBoundingClientRect().bottom)));
      expect(lowest, 'ниже «דילוג» текста нет').toBeLessThanOrEqual(skipBottom.y + skipBottom.height + 1);
      // Кнопка «חזרה» уводит с камеры (экран не залипает).
      await p.getByRole('button', { name: 'חזרה' }).click();
      await expect(p.getByText('המצלמה מוכנה — אפשר לצלם')).toHaveCount(0);
    } finally {
      await saveSession(p, 'new02');
    }
  });
});
